// Calculate days since last activity and assign follow-up step.
// Only process deals that fall in the 3/7/14 day windows (±1 day buffer).
const now = new Date();
const results = [];

for (const item of $input.all()) {
  const deal = item.json;
  const lastActivity = deal.properties?.notes_last_updated || deal.properties?.hs_lastmodifieddate;

  if (!lastActivity) continue;

  const lastDate = new Date(lastActivity);
  const daysSince = Math.floor((now - lastDate) / (1000 * 60 * 60 * 24));

  // Target exact windows with a ±1 day buffer to catch missed runs
  let step = null;
  if (daysSince >= 3 && daysSince <= 4)   step = 1; // Day 3: first nudge
  if (daysSince >= 7 && daysSince <= 8)   step = 2; // Day 7: second touch
  if (daysSince >= 14 && daysSince <= 15) step = 3; // Day 14: final attempt

  if (step === null) continue; // Not in a follow-up window

  results.push({
    json: {
      dealId: deal.id,
      dealName: deal.properties?.dealname || 'Untitled Deal',
      ownerId: deal.properties?.hubspot_owner_id,
      daysSince,
      step,
      amount: deal.properties?.amount || '0'
    }
  });
}

if (results.length === 0) return [{ json: { skip: true, reason: 'No deals in follow-up window today' } }];
return results;
